/// <summary>
/// AR-67 email notification batch job  
/// </summary>
public class METRPAGeneralJournalInterfacePostingController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    // call service class and service class method
    super(classStr(METRPAGeneralJournalInterfacePostingService), methodStr(METRPAGeneralJournalInterfacePostingService, processOperation), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Construct METRPAGeneralJournalInterfacePostingController class
/// </summary>
public static METRPAGeneralJournalInterfacePostingController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METRPAGeneralJournalInterfacePostingController controller;
    controller = new METRPAGeneralJournalInterfacePostingController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

    public static void main(Args _args)

    {
        METRPAGeneralJournalInterfacePostingController controller;

        controller = METRPAGeneralJournalInterfacePostingController::construct();
        controller.parmArgs(_args);
        controller.parmShowDialog(true);
        controller.startOperation();
    }

/// <summary>
/// Caption of a batch job
/// </summary>
public ClassDescription defaultCaption()
{
    return "RPA - General journal interface posting";
}
